// -- network --------------------------------------------------------------
// Requests go through the browser first, so they carry its cookies and pass
// the same bot checks the page did. When the browser refuses another site's
// request (CORS), that site's requests go through the app's transport from
// then on, which has no such limit (like the extension's host access).

const __w2e_transportOrigins = new Set();

function __w2e_transport() {
    return window.__W2E_transport || window.__npia_gm_xmlhttp_request || null;
}

// Some parsers read a login or anti-bot cookie (for example the sbxh content
// path reads a session cookie). The page's own document.cookie can't see
// httpOnly cookies like cf_clearance, so chrome.cookies.get routes the read
// through the same transport, tagged op "cookie", which the app answers from
// the browser's cookie store natively. Returns a cookie object or null.
async function __w2e_getCookie(details) {
    let transport = __w2e_transport();
    if (transport == null || details == null) {
        return null;
    }
    let url = details.url || "";
    if (!url && details.domain) {
        url = "https://" + String(details.domain).replace(/^\./, "") + "/";
    }
    if (!url) {
        return null;
    }
    let result;
    try {
        result = await transport({ op: "cookie", action: "get", url: url, name: details.name || "" });
    } catch (e) {
        return null;
    }
    if (result == null || result.error || result.cookie == null) {
        return null;
    }
    return result.cookie;
}

function __w2e_headerObject(headers) {
    let out = {};
    if (headers == null) {
        return out;
    }
    if (typeof headers.forEach === "function" && !Array.isArray(headers)) {
        headers.forEach((value, name) => { out[name] = value; });
    } else if (Array.isArray(headers)) {
        headers.forEach(pair => { out[pair[0]] = pair[1]; });
    } else {
        Object.keys(headers).forEach(name => { out[name] = headers[name]; });
    }
    return out;
}

function __w2e_hasHeader(headers, name) {
    return Object.keys(headers).some(key => key.toLowerCase() === name);
}

function __w2e_bytesToBase64(bytes) {
    let binary = "";
    for (let i = 0; i < bytes.length; i += 0x8000) {
        binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
    }
    return btoa(binary);
}

function __w2e_base64ToBytes(text) {
    let binary = atob(text || "");
    let bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
}

